def transforms(m):
    def rot(g): return tuple(''.join(g[len(g)-1-j][i] for j in range(len(g))) for i in range(len(g[0])))
    def mir(g): return tuple(row[::-1] for row in g)
    out=[]; g=m
    for _ in range(4):
        out.append(g); out.append(mir(g)); g=rot(g)
    return set(out)
def canon(m): return min(transforms(m))

